def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, find the median of the
    numbers list (which is the middle number if the list has even length).

    Median is used to represent the central tendency of a dataset;
    it is preferred over the average since it is resistant to outliers.
    Median can be thought of as a measure of location.

    Hint: Use [::-1] slicing
    >>> median([1, 2, 3, 4, 5, 6])
    3.5
    """
    numbers_sorted = sorted(numbers)
    middle_num = len(numbers_sorted) // 2
    if len(numbers_sorted) % 2 == 0:
        return round((numbers_sorted[middle_num] + numbers_sorted[middle_num - 1]) / 2, 2)
    else:
        return round(numbers_sorted[middle_num], 2)


