def parse_nested_parens_reverse(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens_reverse('(()()) ((())) () ((())()())')
    [3, 2, 0, 3]
    """

    def inner(depth, start, current_result, parens):
        if parens:
            if not parens[0][0].startswith('(') and not parens[-1][0].endswith(')'):
                current_result.append(depth + 1)
            for next_depth, next_parens in enumerate(reversed(parens)):
                if not next_parens[0].startswith('(') and not next_parens[-1].endswith(')'):
                    inner(next_depth, start - 1, current_result, next_parens)
        return current_result

