    return min(numbers), max(numbers)


def median(numbers: List[float]) -> float:
    """
    Returns the median of a list of numbers.
    """
    n = len(numbers)
    numbers.sort()
    if n % 2:
        mid_index = n//2
        return numbers[mid_index]
    else:
        return sum(numbers[n//2-1:n//2+1]) / 2.0

