def is_balanced_parentheses(paren_string: str) -> bool:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    return True if the parentheses are balanced or False if the string is not.
    A parentheses is balanced if each open brace is properly closed by a properly closed brace.
    >>> is_balanced_parentheses("((()))")
    True
    >>> is_balanced_parentheses("(()())")
    True
    >>> is_balanced_parentheses("((()"))
    False
    """
    stack: List[str] = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                return False
    return not stack

